// macsim: TRAINING simulator. Nine apps drawn after the real macOS ones (Calendar, Finder, Mail, Notes, Reminders,
// Safari, System Settings, Messages, Music), written for training data. They share no layout, content or word pool
// with the test apps of taskenv/. Every element that can be asked for carries data-role and data-name (TE.A).
(() => {
const {esc, A, sym} = TE;
const tb = (s, name, o = {}) => `<span class="tb${o.on ? ' on' : ''}${o.dim ? ' dim' : ''}"${A('button', name, {...o, icon: 1})}>${sym(s, o.size || 17)}</span>`;
const seg = (opts, cur, act, fn) => `<span class="seg">${opts.map(o => `<span class="${o === cur ? 'on' : ''}"${A('tab', o, {act, arg: o, state: o === cur ? 'selected' : '', fn: fn ? fn(o) : ''})}>${esc(o)}</span>`).join('')}</span>`;
const srch = (name = 'Search', w = '') => `<span class="srch" style="${w}"${A('search field', name, {fn: 'search|type what to look for'})}>${sym('magnifyingglass', 13)}<input type="text" placeholder="Search" data-input="search" data-focus="search"></span>`;
const si = (cls, on, role, name, o, inner) => `<div class="si ${cls}${on ? ' on' : ''}"${A(role, name, {...o, state: on ? 'selected' : (o.state || '')})}>${inner}</div>`;
const alertBox = al => !al ? '' : `<div class="sheet-dim"><div class="alert${al.wide ? ' wide' : ''}">${al.icon ? `<img src="/app/${al.icon}">` : ''}<div class="col"><h4>${esc(al.title)}</h4><p>${esc(al.text)}</p>` +
  `<div class="row${al.wide ? ' wide' : ''}">${al.buttons.map((b, i) => `<span class="pbtn big${b === al.def ? ' def' : ''}${/delete|erase|remove|discard/i.test(b) && b !== al.def ? ' red' : ''}"${A('button', b, {act: 'alert', arg: b})}>${esc(b)}</span>`).join('')}</div></div></div></div>`;
const answer = (s, b) => { s.ui.alert = null; s.answer = b; };
const hueBg = h => `linear-gradient(135deg, hsl(${h} 70% 62%), hsl(${(h + 40) % 360} 65% 45%))`;
const avatar = (n, h, size = 32) => `<span class="avatar" style="width:${size}px;height:${size}px;font-size:${size * .4}px;background:${hueBg(h)}">${esc(n.split(' ').map(x => x[0]).slice(0, 2).join(''))}</span>`;
const editMenu = {label: 'Edit', items: [{label: 'Undo', shortcut: '⌘Z'}, {label: 'Redo', shortcut: '⇧⌘Z', disabled: true}, '-', {label: 'Cut', shortcut: '⌘X'}, {label: 'Copy', shortcut: '⌘C'}, {label: 'Paste', shortcut: '⌘V'}, {label: 'Select All', shortcut: '⌘A'}, '-', {label: 'Find', items: [{label: 'Find…', shortcut: '⌘F'}, {label: 'Find Next', shortcut: '⌘G'}]}]};

// ------------------------------------------------------------------ Calendar
const D = iso => new Date(iso + 'T00:00:00Z'), ISO = d => d.toISOString().slice(0, 10), add = (iso, n) => { const d = D(iso); d.setUTCDate(d.getUTCDate() + n); return ISO(d); };
const MON = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'], WD = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const dow = iso => (D(iso).getUTCDay() + 6) % 7, monday = iso => add(iso, -dow(iso)), first = iso => iso.slice(0, 8) + '01';
const hm = h => { const m = Math.round((h % 1) * 60), x = Math.floor(h) % 12 || 12; return x + (m ? ':' + String(m).padStart(2, '0') : '') + (h < 12 ? ' AM' : ' PM'); };
const dayName = iso => MON[D(iso).getUTCMonth()] + ' ' + D(iso).getUTCDate();
TE.register('calendar', {
  title: 'Calendar', size: [1000, 640],
  render(s) {
    const u = s.ui, a = D(u.anchor), unit = u.view.toLowerCase(), col = id => (s.cals.find(c => c.id === id) || {}).color, shown = e => (s.cals.find(c => c.id === e.cal) || {}).on;
    const side = !u.side ? '' : `<div class="side cal-side"><div class="sh">iCloud</div>` + s.cals.map(c => `<div class="si"${A('checkbox', c.name, {act: 'cal', arg: c.id, state: c.on ? 'checked' : 'unchecked', fn: `${c.on ? 'hide' : 'show'} the ${c.name} calendar`, noun: 'calendar'})}><span class="cb${c.on ? ' on' : ''}" style="${c.on ? 'background:' + c.color : ''}">${c.on ? sym('checkmark', 9) : ''}</span><span>${esc(c.name)}</span></div>`).join('') +
      `<div class="sh">Other</div>` + s.other.map(c => `<div class="si"${A('checkbox', c.name, {act: 'oth', arg: c.name, state: c.on ? 'checked' : 'unchecked', noun: 'calendar'})}><span class="cb${c.on ? ' on' : ''}" style="${c.on ? 'background:' + c.color : ''}">${c.on ? sym('checkmark', 9) : ''}</span><span>${esc(c.name)}</span></div>`).join('') + `</div>`;
    const bar = `<div class="tbar" data-windrag style="${u.side ? '' : 'padding-left:84px'}">${tb('calendar', 'Calendars', {act: 'side', fn: 'show or hide the list of calendars', on: u.side})}${tb('plus', 'New Event', {fn: 'add an event|create a new event'})}<span class="sp"></span>` +
      seg(['Day', 'Week', 'Month', 'Year'], u.view, 'view', o => `show the calendar by ${o.toLowerCase()}|switch to ${o} view`) + `<span class="sp"></span>${srch()}</div>`;
    const title = u.view === 'Year' ? `<b>${a.getUTCFullYear()}</b>` : u.view === 'Day' ? `<b>${a.getUTCDate()} ${MON[a.getUTCMonth()]}</b> ${a.getUTCFullYear()}` : `<b>${MON[a.getUTCMonth()]}</b> ${a.getUTCFullYear()}`;
    const head = `<div class="cal-head"><span class="cal-title">${title}</span><span class="cal-nav"><span class="pbtn arrow"${A('button', 'Previous', {act: 'nav', arg: -1, fn: `go to the previous ${unit}|go back one ${unit}`, icon: 1, noun: 'arrow'})}>${sym('chevron.left', 10)}</span>` +
      `<span class="pbtn"${A('button', 'Today', {act: 'today', fn: 'go to the current date|jump back to today'})}>Today</span><span class="pbtn arrow"${A('button', 'Next', {act: 'nav', arg: 1, fn: `go to the next ${unit}|go forward one ${unit}`, icon: 1, noun: 'arrow'})}>${sym('chevron.right', 10)}</span></span></div>`;
    const evs = iso => s.events.filter(e => e.date === iso && shown(e)).sort((x, y) => x.start - y.start);
    let body;
    if (u.view === 'Month') {
      const start = monday(first(u.anchor));
      body = `<div class="cal-wd">${WD.map(d => `<span>${d}</span>`).join('')}</div><div class="cal-month">` + Array.from({length: 42}, (_, i) => { const iso = add(start, i), other = iso.slice(0, 7) !== u.anchor.slice(0, 7), ev = evs(iso);
        return `<div class="c-cell${other ? ' dim' : ''}${dow(iso) > 4 ? ' we' : ''}"${A('cell', dayName(iso), {act: 'day', arg: iso, noun: 'day'})}><span class="c-num${iso === s.today ? ' today' : ''}">${D(iso).getUTCDate() === 1 ? MON[D(iso).getUTCMonth()].slice(0, 3) + ' 1' : D(iso).getUTCDate()}</span>` +
          ev.slice(0, 3).map(e => `<div class="c-chip"${A('event', e.title, {act: 'ev', arg: e.id})}><i style="background:${col(e.cal)}"></i><span>${esc(e.title)}</span><em>${hm(e.start).replace(' ', '')}</em></div>`).join('') + (ev.length > 3 ? `<div class="c-more">${ev.length - 3} more…</div>` : '') + `</div>`; }).join('') + `</div>`;
    } else if (u.view === 'Year') {
      body = `<div class="cal-year">` + MON.map((m, k) => { const f = `${a.getUTCFullYear()}-${String(k + 1).padStart(2, '0')}-01`, st = monday(f);
        return `<div class="c-mini"${A('cell', m + ' ' + a.getUTCFullYear(), {act: 'month', arg: f, noun: 'month'})}><b>${m}</b><div>${WD.map(d => `<i>${d[0]}</i>`).join('')}${Array.from({length: 42}, (_, i) => { const iso = add(st, i); return `<span class="${iso.slice(0, 7) !== f.slice(0, 7) ? 'o' : iso === s.today ? 't' : ''}">${D(iso).getUTCDate()}</span>`; }).join('')}</div></div>`; }).join('') + `</div>`;
    } else {
      const days = u.view === 'Day' ? [u.anchor] : Array.from({length: 7}, (_, i) => add(monday(u.anchor), i)), H0 = 7, H1 = 19;
      body = `<div class="cal-wkhead" style="--n:${days.length}"><span></span>${days.map(iso => `<span class="${iso === s.today ? 'today' : ''}"${A('column header', WD[dow(iso)] + ' ' + D(iso).getUTCDate(), {noun: 'day'})}>${WD[dow(iso)]} <b>${D(iso).getUTCDate()}</b></span>`).join('')}</div>` +
        `<div class="cal-week" style="--n:${days.length}"><div class="c-hours">${Array.from({length: H1 - H0}, (_, i) => `<span>${hm(H0 + i).replace(':00', '')}</span>`).join('')}</div>` +
        days.map(iso => `<div class="c-col${dow(iso) > 4 ? ' we' : ''}">${evs(iso).filter(e => e.start >= H0 && e.start < H1).map(e => `<div class="c-ev" style="top:${(e.start - H0) * 40}px;height:${Math.max(18, e.dur * 40 - 2)}px;--c:${col(e.cal)}"${A('event', e.title, {act: 'ev', arg: e.id})}><b>${esc(e.title)}</b><span>${hm(e.start)}</span></div>`).join('')}</div>`).join('') + `</div>`;
    }
    const pe = s.events.find(e => e.id === u.pop), pop = !pe ? '' : `<div class="c-pop"><h4>${esc(pe.title)}</h4><p>${dayName(pe.date)}, ${hm(pe.start)} to ${hm(pe.start + pe.dur)}</p>` +
      `<div class="c-prow"><span>Calendar</span><span class="popup"${A('pop-up button', 'Calendar', {fn: 'choose which calendar this event is in'})}><i style="width:9px;height:9px;border-radius:50%;background:${col(pe.cal)}"></i>${esc((s.cals.find(c => c.id === pe.cal) || {}).name)}<em>${sym('chevron.down', 9)}</em></span></div>` +
      `<div class="c-prow"><span>Alert</span><span class="popup"${A('pop-up button', 'Alert', {fn: 'set when to be reminded'})}>None<em>${sym('chevron.down', 9)}</em></span></div><div class="c-prow"><span class="pbtn"${A('button', 'Add Invitees')}>Add Invitees</span><span class="pbtn red"${A('button', 'Delete Event', {act: 'del', arg: pe.id})}>Delete Event</span></div></div>`;
    return `<div class="cal" style="display:flex;flex:1;min-width:0;position:relative">${side}<div class="pane">${bar}${head}${body}</div>${pop}${alertBox(u.alert)}</div>`;
  },
  on: {
    view(s, v) { s.ui.view = v; s.ui.pop = null; }, side(s) { s.ui.side = !s.ui.side; }, today(s) { s.ui.anchor = s.today; s.ui.pop = null; },
    nav(s, d) { const u = s.ui, a = D(u.anchor); d = +d; if (u.view === 'Month') { a.setUTCDate(1); a.setUTCMonth(a.getUTCMonth() + d); u.anchor = ISO(a); } else if (u.view === 'Year') { a.setUTCFullYear(a.getUTCFullYear() + d); u.anchor = ISO(a); } else u.anchor = add(u.anchor, d * (u.view === 'Week' ? 7 : 1)); u.pop = null; },
    cal(s, id) { const c = s.cals.find(c => c.id === id); c.on = !c.on; }, oth(s, n) { const c = s.other.find(c => c.name === n); c.on = !c.on; },
    ev(s, id) { s.ui.pop = s.ui.pop === id ? null : id; }, day(s, iso) { s.ui.anchor = iso; s.ui.pop = null; }, month(s, iso) { s.ui.anchor = iso; s.ui.view = 'Month'; },
    del(s, id) { s.events = s.events.filter(e => e.id !== id); s.ui.pop = null; }, alert: answer, search(s, _, t) { s.ui.q = t; },
  },
  menus(s) { return [{label: 'File', items: [{label: 'New Event', shortcut: '⌘N'}, {label: 'New Calendar', shortcut: '⌥⌘N'}, '-', {label: 'Import…'}, {label: 'Export', items: [{label: 'Export…'}, {label: 'Calendar Archive…'}]}, '-', {label: 'Print…', shortcut: '⌘P'}]}, editMenu,
    {label: 'View', items: [{label: 'By Day', shortcut: '⌘1', act: 'view', arg: 'Day', checked: s.ui.view === 'Day'}, {label: 'By Week', shortcut: '⌘2', act: 'view', arg: 'Week', checked: s.ui.view === 'Week'}, {label: 'By Month', shortcut: '⌘3', act: 'view', arg: 'Month', checked: s.ui.view === 'Month'}, {label: 'By Year', shortcut: '⌘4', act: 'view', arg: 'Year', checked: s.ui.view === 'Year'}, '-',
      {label: 'Go to Today', shortcut: '⌘T', act: 'today'}, {label: 'Go to Date…', shortcut: '⇧⌘T'}, '-', {label: s.ui.side ? 'Hide Calendar List' : 'Show Calendar List', act: 'side'}, {label: 'Show Declined Events'}]}]; },
});

// ------------------------------------------------------------------ Finder
const FSYM = {folder: 'folder', pdf: 'doc.text', text: 'doc.text', image: 'photo', audio: 'music.note', zip: 'doc.zipper', app: 'plus.app', sheet: 'doc.text.image', movie: 'play.rectangle'};
const FKIND = {folder: 'Folder', pdf: 'PDF Document', text: 'Plain Text', image: 'HEIF Image', audio: 'MPEG-4 Audio', zip: 'ZIP archive', app: 'Application', sheet: 'Numbers Spreadsheet', movie: 'QuickTime movie'};
TE.register('finder', {
  title: 'Finder', size: [920, 540],
  render(s) {
    const u = s.ui, here = s.items.filter(i => i.parent === u.path), name = id => (s.places.concat(s.cloud, s.locs).find(p => p.id === id) || s.items.find(i => i.id === id) || {}).name || '';
    const row = p => si('', u.path === p.id, 'sidebar item', p.name, {act: 'go', arg: p.id, fn: 'go to ' + p.name}, `${sym(p.sym, 16)}<span>${esc(p.name)}</span>`);
    const side = `<div class="side"><div class="sh">Favourites</div>${s.places.map(row).join('')}<div class="sh">iCloud</div>${s.cloud.map(row).join('')}<div class="sh">Locations</div>${s.locs.map(row).join('')}<div class="sh">Tags</div>` +
      s.tags.map(t => `<div class="si"${A('sidebar item', t.name, {fn: `show files tagged ${t.name}`, noun: 'tag'})}><i class="tagdot" style="background:${t.color}"></i><span>${esc(t.name)}</span></div>`).join('') + `</div>`;
    const V = [['icons', 'square.grid.2x2', 'Icon view', 'show items as icons'], ['list', 'list.bullet', 'List view', 'show items in a list'], ['columns', 'rectangle.split.3x1', 'Column view', 'show items in columns'], ['gallery', 'rectangle.stack', 'Gallery view', 'show items in a gallery']];
    const bar = `<div class="tbar" data-windrag>${tb('chevron.left', 'Back', {act: 'back', dim: !u.back.length, fn: 'go back to the previous folder', noun: 'arrow'})}${tb('chevron.right', 'Forward', {act: 'fwd', dim: !u.fwd.length, fn: 'go forward', noun: 'arrow'})}<span class="ttl">${esc(name(u.path))}</span><span class="sp"></span>` +
      `<span class="tgrp">${V.map(([v, sy, n, fn]) => tb(sy, n, {act: 'view', arg: v, on: u.view === v, state: u.view === v ? 'selected' : '', fn})).join('')}</span>${tb('square.grid.3x3', 'Group', {fn: 'change how items are grouped'})}${tb('square.and.arrow.up', 'Share', {fn: 'share the selected items'})}${tb('ellipsis.circle', 'Action', {fn: 'more actions for the selected items'})}${srch()}</div>`;
    const ic = (i, z) => `<span class="f-ic k-${i.kind}">${sym(FSYM[i.kind] || 'doc', z)}</span>`;
    const body = (u.view === 'list' || u.view === 'columns')
      ? `<div class="f-hd"><span>Name</span><span>Date Modified</span><span>Size</span><span>Kind</span></div><div class="f-rows">${here.map(i => `<div class="f-row${u.sel === i.id ? ' on' : ''}"${A('file', i.name, {act: 'sel', arg: i.id, state: u.sel === i.id ? 'selected' : '', noun: i.kind === 'folder' ? 'folder' : 'file'})} data-dbl="open" data-ctx="${i.id}">${ic(i, 16)}<span class="nm">${esc(i.name)}</span><span>${esc(i.date)}</span><span>${esc(i.size)}</span><span>${FKIND[i.kind]}</span></div>`).join('')}</div>`
      : `<div class="f-grid">${here.map(i => `<div class="f-cell${u.sel === i.id ? ' on' : ''}"${A('file', i.name, {act: 'sel', arg: i.id, state: u.sel === i.id ? 'selected' : '', noun: i.kind === 'folder' ? 'folder' : 'file'})} data-dbl="open" data-ctx="${i.id}">${ic(i, 52)}<span class="nm">${esc(i.name)}</span></div>`).join('')}</div>`;
    const chain = []; for (let p = u.path; p; p = (s.items.find(i => i.id === p) || {}).parent) chain.unshift(p);
    const path = `<div class="f-path">${['Macintosh HD', 'Users', s.user].concat(chain.map(name)).map((n, k, all) => `<span${A('path item', n, {fn: `go to the ${n} folder`})}>${sym(k < 3 && k !== 2 ? 'externaldrive' : 'folder', 12)}${esc(n)}</span>${k < all.length - 1 ? '<em>›</em>' : ''}`).join('')}</div>`;
    return `<div class="fin" style="display:flex;flex:1;min-width:0;position:relative">${side}<div class="pane">${bar}${body}${path}<div class="f-st">${here.length} items, ${esc(s.free)} available</div></div>${alertBox(u.alert)}</div>`;
  },
  on: {
    go(s, id) { const u = s.ui; if (u.path !== id) { u.back.push(u.path); u.fwd = []; } u.path = id; u.sel = null; }, back(s) { const u = s.ui; if (u.back.length) { u.fwd.push(u.path); u.path = u.back.pop(); u.sel = null; } },
    fwd(s) { const u = s.ui; if (u.fwd.length) { u.back.push(u.path); u.path = u.fwd.pop(); u.sel = null; } }, view(s, v) { s.ui.view = v; }, sel(s, id) { s.ui.sel = id; },
    open(s, id) { const i = s.items.find(i => i.id === id); if (i && i.kind === 'folder') this.on.go(s, id); else if (i) s.opened = i.name; }, alert: answer, search(s, _, t) { s.ui.q = t; },
    trash(s, id) { const i = s.items.find(i => i.id === (id || s.ui.sel)); if (i) { i.parent = 'bin'; s.ui.sel = null; } }, newfolder(s) { s.items.push({id: 'n' + s.items.length, name: 'untitled folder', kind: 'folder', parent: s.ui.path, date: 'Today', size: '--'}); },
  },
  context(s, id) { s.ui.sel = id; return [{label: 'Open', act: 'open'}, {label: 'Open With', items: [{label: 'Preview'}, {label: 'TextEdit'}, {label: 'Other…'}]}, '-', {label: 'Move to Bin', act: 'trash'}, '-', {label: 'Get Info'}, {label: 'Rename'}, {label: 'Compress'}, {label: 'Duplicate'}, {label: 'Make Alias'}, {label: 'Quick Look'}, '-', {label: 'Copy'}, {label: 'Share…'}, '-', {label: 'Tags…'}]; },
  menus(s) { return [{label: 'File', items: [{label: 'New Finder Window', shortcut: '⌘N'}, {label: 'New Folder', shortcut: '⇧⌘N', act: 'newfolder'}, {label: 'New Smart Folder'}, {label: 'New Tab', shortcut: '⌘T'}, '-', {label: 'Open', shortcut: '⌘O'}, {label: 'Close Window', shortcut: '⌘W', sys: 'close'}, '-', {label: 'Get Info', shortcut: '⌘I'}, {label: 'Rename'}, {label: 'Duplicate', shortcut: '⌘D'}, '-', {label: 'Move to Bin', shortcut: '⌘⌫', act: 'trash', disabled: !s.ui.sel}, {label: 'Find', shortcut: '⌘F'}]}, editMenu,
    {label: 'View', items: [{label: 'as Icons', shortcut: '⌘1', act: 'view', arg: 'icons', checked: s.ui.view === 'icons'}, {label: 'as List', shortcut: '⌘2', act: 'view', arg: 'list', checked: s.ui.view === 'list'}, {label: 'as Columns', shortcut: '⌘3', act: 'view', arg: 'columns', checked: s.ui.view === 'columns'}, {label: 'as Gallery', shortcut: '⌘4', act: 'view', arg: 'gallery', checked: s.ui.view === 'gallery'}, '-', {label: 'Sort By', items: [{label: 'Name'}, {label: 'Kind'}, {label: 'Date Modified'}, {label: 'Size'}]}, {label: 'Show Path Bar'}, {label: 'Show Status Bar'}]},
    {label: 'Go', items: [{label: 'Back', shortcut: '⌘[', act: 'back'}, {label: 'Forward', shortcut: '⌘]', act: 'fwd'}, {label: 'Enclosing Folder', shortcut: '⌘↑'}, '-', ...s.places.map(p => ({label: p.name, act: 'go', arg: p.id})), '-', {label: 'Go to Folder…', shortcut: '⇧⌘G'}, {label: 'Connect to Server…', shortcut: '⌘K'}]}]; },
});

// ------------------------------------------------------------------ Mail
TE.register('mail', {
  title: 'Mail', size: [1060, 620],
  render(s) {
    const u = s.ui, list = s.msgs.filter(m => u.box === 'flagged' ? m.flag : m.box === u.box), cur = s.msgs.find(m => m.id === u.sel), box = s.boxes.find(b => b.id === u.box) || {name: ''};
    const side = `<div class="side">` + ['Favourites', 'Smart Mailboxes', s.account].map((h, k) => `<div class="sh">${esc(h)}</div>` + s.boxes.filter(b => b.grp === k).map(b => si('', u.box === b.id, 'mailbox', b.name, {act: 'box', arg: b.id, fn: `show the ${b.name} mailbox`}, `${sym(b.sym, 16)}<span>${esc(b.name)}</span>${b.n ? `<span class="n">${b.n}</span>` : ''}`)).join('')).join('') + `</div>`;
    const d = !cur, bar = `<div class="tbar" data-windrag><span class="ttl">${esc(box.name)}<div class="sub">${list.length} messages${list.filter(m => m.unread).length ? ', ' + list.filter(m => m.unread).length + ' unread' : ''}</div></span><span class="sp"></span>` +
      tb('envelope', 'Get Mail', {fn: 'check for new mail'}) + tb('square.and.pencil', 'New Message', {act: 'compose', fn: 'write a new email|compose a message'}) + `<i class="gap"></i>` + tb('archivebox', 'Archive', {act: 'arch', dim: d, fn: 'archive the selected message'}) + tb('trash', 'Delete', {act: 'del', dim: d, fn: 'delete the selected message|move the message to the bin'}) + tb('arrow.up.bin', 'Junk', {dim: d, fn: 'mark the message as junk'}) + `<i class="gap"></i>` +
      tb('arrowshape.turn.up.left', 'Reply', {dim: d, fn: 'reply to the sender'}) + tb('arrowshape.turn.up.left.2', 'Reply All', {dim: d, fn: 'reply to everyone'}) + tb('arrowshape.turn.up.right', 'Forward', {dim: d, fn: 'forward the message to someone else'}) + `<i class="gap"></i>` + tb('flag', 'Flag', {act: 'flag', dim: d, on: cur && cur.flag, fn: 'flag the selected message'}) + tb('bell.slash', 'Mute', {dim: d, fn: 'mute this conversation'}) + tb('folder', 'Move', {dim: d, fn: 'move the message to another mailbox'}) + `<span class="sp"></span>${srch()}</div>`;
    const rows = `<div class="m-list">${list.map(m => `<div class="m-row${u.sel === m.id ? ' on' : ''}"${A('message', `${m.from}: ${m.subject}`, {act: 'sel', arg: m.id, state: m.unread ? 'unread' : '', noun: 'email'})} data-ctx="${m.id}"><i class="dot${m.unread ? ' on' : ''}"></i><div><div class="r1"><b>${esc(m.from)}</b><span>${esc(m.date)}</span></div><div class="r2">${esc(m.subject)}${m.flag ? `<i class="fl">${sym('flag', 11)}</i>` : ''}</div><div class="r3">${esc(m.preview)}</div></div></div>`).join('')}</div>`;
    const read = cur ? `<div class="m-read"><div class="m-h">${avatar(cur.from, cur.hue, 38)}<div><div class="r1"><b>${esc(cur.from)}</b><span>${esc(cur.date)}</span></div><div>${esc(cur.subject)}</div><div class="sub">To: ${esc(s.me)}</div></div></div><div class="m-b">${cur.body.split('\n').map(p => `<p>${esc(p)}</p>`).join('')}</div></div>` : `<div class="m-read none">No Message Selected</div>`;
    const comp = !u.compose ? '' : `<div class="m-comp"><div class="m-ct">${tb('paperplane', 'Send', {act: 'send', fn: 'send this email'})}<b>New Message</b><span class="sp"></span>${tb('paperclip', 'Attach', {fn: 'attach a file'})}${tb('textformat', 'Format', {fn: 'show the formatting bar'})}${tb('xmark', 'Close', {act: 'compose', fn: 'discard this draft'})}</div>` +
      ['To', 'Cc', 'Subject'].map(f => `<label><span>${f}:</span><input type="text"${A('text field', f, {fn: f === 'To' ? 'type the recipient' : f === 'Subject' ? 'type the subject' : ''})} data-input="draft" data-arg="${f}" data-focus="c-${f}"></label>`).join('') + `<textarea${A('text field', 'Message body', {fn: 'type the message'})} data-input="draft" data-arg="body" data-focus="c-body"></textarea></div>`;
    return `<div class="mail" style="display:flex;flex:1;min-width:0;position:relative">${side}<div class="pane">${bar}<div class="m-split">${rows}${read}</div></div>${comp}${alertBox(u.alert)}</div>`;
  },
  on: {
    box(s, id) { s.ui.box = id; s.ui.sel = null; }, sel(s, id) { s.ui.sel = id; const m = s.msgs.find(m => m.id === id); if (m) m.unread = false; }, flag(s) { const m = s.msgs.find(m => m.id === s.ui.sel); if (m) m.flag = !m.flag; },
    arch(s) { const m = s.msgs.find(m => m.id === s.ui.sel); if (m) { m.box = 'archive'; s.ui.sel = null; } }, del(s) { const m = s.msgs.find(m => m.id === s.ui.sel); if (m) { m.box = 'bin'; s.ui.sel = null; } },
    compose(s) { s.ui.compose = !s.ui.compose; s.ui.draft = {}; if (s.ui.compose) TE.focus('c-To'); }, draft(s, f, t) { s.ui.draft[f] = t; }, send(s) { if ((s.ui.draft.To || '').trim()) { s.sent.push({...s.ui.draft}); s.ui.compose = false; } }, alert: answer, search(s, _, t) { s.ui.q = t; },
  },
  context(s, id) { s.ui.sel = id; const m = s.msgs.find(m => m.id === id); return [{label: 'Reply'}, {label: 'Reply All'}, {label: 'Forward'}, '-', {label: m.unread ? 'Mark as Read' : 'Mark as Unread'}, {label: m.flag ? 'Remove Flag' : 'Flag', act: 'flag'}, {label: 'Move to Junk'}, {label: 'Mute'}, '-', {label: 'Archive', act: 'arch'}, {label: 'Delete', act: 'del'}, {label: 'Move to', items: s.boxes.filter(b => b.grp !== 1).map(b => ({label: b.name}))}]; },
  menus(s) { return [{label: 'File', items: [{label: 'New Message', shortcut: '⌘N', act: 'compose'}, {label: 'New Viewer Window', shortcut: '⌥⌘N'}, '-', {label: 'Save', shortcut: '⌘S', disabled: true}, {label: 'Print…', shortcut: '⌘P'}]}, editMenu, {label: 'View', items: [{label: 'Sort By', items: [{label: 'Date'}, {label: 'From'}, {label: 'Subject'}]}, {label: 'Show Tab Bar'}, {label: 'Hide Sidebar', shortcut: '⌃⌘S'}, {label: 'Use Column Layout'}]},
    {label: 'Mailbox', items: [{label: 'Take All Accounts Online'}, {label: 'Get All New Mail', shortcut: '⇧⌘N'}, '-', {label: 'New Mailbox…'}, {label: 'New Smart Mailbox…'}, '-', {label: 'Erase Deleted Items', items: [{label: 'In All Accounts…'}]}, {label: 'Erase Junk Mail', shortcut: '⌥⌘J'}]},
    {label: 'Message', items: [{label: 'Reply', shortcut: '⌘R'}, {label: 'Reply All', shortcut: '⇧⌘R'}, {label: 'Forward', shortcut: '⇧⌘F'}, '-', {label: 'Flag', shortcut: '⇧⌘L', act: 'flag'}, {label: 'Archive', shortcut: '⌃⌘A', act: 'arch'}, {label: 'Move to Junk', shortcut: '⇧⌘J'}]}, {label: 'Format', items: [{label: 'Show Fonts', shortcut: '⌘T'}, {label: 'Make Plain Text', shortcut: '⇧⌘T'}]}]; },
});

// ------------------------------------------------------------------ Notes
TE.register('notes', {
  title: 'Notes', size: [980, 600],
  render(s) {
    const u = s.ui, list = s.notes.filter(n => n.folder === u.folder), cur = s.notes.find(n => n.id === u.sel);
    const side = !u.side ? '' : `<div class="side"><div class="sh">iCloud</div>${s.folders.map(f => si('', u.folder === f.id, 'folder', f.name, {act: 'folder', arg: f.id, fn: `show the notes in ${f.name}`}, `${sym('folder', 16)}<span>${esc(f.name)}</span><span class="n">${s.notes.filter(n => n.folder === f.id).length}</span>`)).join('')}<div class="sh">Tags</div><div class="ntags">${s.tags.map(t => `<span${A('tag', '#' + t, {fn: `show notes tagged ${t}`})}>#${esc(t)}</span>`).join('')}</div><span class="sp" style="flex:1"></span><div class="si"${A('button', 'New Folder', {fn: 'add a folder'})}>${sym('plus.circle', 15)}<span>New Folder</span></div></div>`;
    const bar = `<div class="tbar" data-windrag style="${u.side ? '' : 'padding-left:84px'}">${tb('sidebar.left', 'Sidebar', {act: 'side', fn: 'show or hide the folders'})}<span class="tgrp">${tb('list.bullet', 'List view', {act: 'view', arg: 'list', on: u.view === 'list', fn: 'show notes in a list'})}${tb('square.grid.2x2', 'Gallery view', {act: 'view', arg: 'gallery', on: u.view === 'gallery', fn: 'show notes as thumbnails'})}</span>${tb('trash', 'Delete', {act: 'del', dim: !cur, fn: 'delete this note'})}<span class="sp"></span>` +
      tb('square.and.pencil', 'New Note', {act: 'new', fn: 'create a note|write a new note'}) + tb('textformat', 'Format', {fn: 'choose a text style'}) + tb('checklist', 'Checklist', {fn: 'make a checklist'}) + tb('rectangle.split.3x1', 'Table', {fn: 'add a table'}) + tb('photo', 'Media', {fn: 'add a photo or scan'}) + `<span class="sp"></span>` + tb('lock', 'Lock', {fn: 'lock this note'}) + tb('square.and.arrow.up', 'Share', {fn: 'share this note'}) + srch() + `</div>`;
    const rows = u.view === 'gallery' ? `<div class="n-gal">${list.map(n => `<div class="n-card${u.sel === n.id ? ' on' : ''}"${A('note', n.title, {act: 'sel', arg: n.id})}><div><b>${esc(n.title)}</b><p>${esc(n.snippet)}</p></div><span>${esc(n.title)}</span><em>${esc(n.date)}</em></div>`).join('')}</div>`
      : `<div class="n-list">${list.map(n => `<div class="n-row${u.sel === n.id ? ' on' : ''}"${A('note', n.title, {act: 'sel', arg: n.id, state: u.sel === n.id ? 'selected' : ''})}><b>${n.pinned ? sym('pin', 10) : ''}${esc(n.title)}</b><span><em>${esc(n.date)}</em> ${esc(n.snippet)}</span></div>`).join('')}</div>`;
    const ed = u.view === 'gallery' ? '' : cur ? `<div class="n-ed"><div class="n-date">${esc(cur.long)}</div><h2>${esc(cur.title)}</h2>${cur.body.map(l => l.startsWith('[') ? `<div class="n-chk"><i class="${l[1] === 'x' ? 'on' : ''}"${A('checkbox', l.slice(4), {state: l[1] === 'x' ? 'checked' : 'unchecked', noun: 'circle'})}></i>${esc(l.slice(4))}</div>` : `<p>${esc(l)}</p>`).join('')}</div>` : `<div class="n-ed"></div>`;
    return `<div class="notes" style="display:flex;flex:1;min-width:0;position:relative">${side}<div class="pane">${bar}<div class="n-split">${rows}${ed}</div></div>${alertBox(u.alert)}</div>`;
  },
  on: { folder(s, id) { s.ui.folder = id; s.ui.sel = (s.notes.find(n => n.folder === id) || {}).id || null; }, sel(s, id) { s.ui.sel = id; if (s.ui.view === 'gallery') s.ui.view = 'list'; }, view(s, v) { s.ui.view = v; }, side(s) { s.ui.side = !s.ui.side; },
    del(s) { s.notes = s.notes.filter(n => n.id !== s.ui.sel); s.ui.sel = null; }, new(s) { const id = 'x' + s.notes.length; s.notes.unshift({id, folder: s.ui.folder, title: 'New Note', snippet: 'No additional text', date: 'Now', long: 'Today', body: [], pinned: false}); s.ui.sel = id; s.ui.view = 'list'; }, alert: answer, search(s, _, t) { s.ui.q = t; } },
  menus(s) { return [{label: 'File', items: [{label: 'New Note', shortcut: '⌘N', act: 'new'}, {label: 'New Folder', shortcut: '⇧⌘N'}, '-', {label: 'Lock Note'}, {label: 'Duplicate Note'}, '-', {label: 'Pin Note'}, {label: 'Export as PDF…'}, {label: 'Print…', shortcut: '⌘P'}]}, editMenu,
    {label: 'Format', items: [{label: 'Title', shortcut: '⇧⌘T'}, {label: 'Heading', shortcut: '⇧⌘H'}, {label: 'Body', shortcut: '⇧⌘B'}, '-', {label: 'Checklist', shortcut: '⇧⌘L'}, {label: 'Table', shortcut: '⌥⌘T'}]}, {label: 'View', items: [{label: 'as List', shortcut: '⌘1', act: 'view', arg: 'list', checked: s.ui.view === 'list'}, {label: 'as Gallery', shortcut: '⌘2', act: 'view', arg: 'gallery', checked: s.ui.view === 'gallery'}, '-', {label: s.ui.side ? 'Hide Folders' : 'Show Folders', act: 'side'}, {label: 'Show Attachments Browser'}]}]; },
});

// ------------------------------------------------------------------ Reminders
TE.register('reminders', {
  title: 'Reminders', size: [860, 580],
  render(s) {
    const u = s.ui, sm = s.smart.find(x => x.id === u.list), li = s.lists.find(x => x.id === u.list), head = sm || li || {name: '', color: '#888'};
    const items = s.items.filter(i => sm ? (sm.id === 'flagged' ? i.flag && !i.done : sm.id === 'done' ? i.done : sm.id === 'today' ? i.due === 'Today' && !i.done : sm.id === 'sched' ? i.due && !i.done : !i.done) : i.list === u.list && (!i.done || u.show));
    const n = id => s.items.filter(i => id === 'flagged' ? i.flag && !i.done : id === 'done' ? i.done : id === 'today' ? i.due === 'Today' && !i.done : id === 'sched' ? i.due && !i.done : !i.done).length;
    const side = `<div class="side rem-side"><div style="padding:0 10px 8px">${srch('Search', 'width:100%')}</div><div class="r-tiles">${s.smart.map(t => `<div class="r-tile${u.list === t.id ? ' on' : ''}"${A('button', t.name, {act: 'list', arg: t.id, state: u.list === t.id ? 'selected' : '', fn: t.fn})}><span class="r-ti" style="background:${t.color}">${sym(t.sym, 14)}</span><b>${n(t.id)}</b><em>${esc(t.name)}</em></div>`).join('')}</div>` +
      `<div class="sh">My Lists</div>${s.lists.map(l => si('', u.list === l.id, 'list', l.name, {act: 'list', arg: l.id, fn: `show the ${l.name} list`}, `<span class="r-li" style="background:${l.color}">${sym('list.bullet', 11)}</span><span>${esc(l.name)}</span><span class="n">${s.items.filter(i => i.list === l.id && !i.done).length}</span>`)).join('')}<span style="flex:1"></span><div class="si"${A('button', 'Add List', {fn: 'make a new list'})}>${sym('plus.circle', 15)}<span>Add List</span></div></div>`;
    const bar = `<div class="tbar clear" data-windrag><span class="sp"></span>${tb('square.and.arrow.up', 'Share', {fn: 'share this list'})}${tb('plus', 'New Reminder', {act: 'add', fn: 'add a reminder'})}</div>`;
    const rows = items.map(i => `<div class="r-row"><i class="r-c${i.done ? ' on' : ''}" style="--c:${(s.lists.find(l => l.id === i.list) || {}).color}"${A('checkbox', i.title, {act: 'tog', arg: i.id, state: i.done ? 'completed' : 'not completed', fn: `mark “${i.title}” as ${i.done ? 'not completed' : 'completed'}`, noun: 'circle'})}></i><div><span class="${i.done ? 'dn' : ''}">${esc(i.title)}</span>${i.note || i.due ? `<small>${esc([i.due, i.note].filter(Boolean).join('  ·  '))}</small>` : ''}</div>${i.flag ? `<i class="r-f">${sym('flag', 12)}</i>` : ''}</div>`).join('');
    return `<div class="rem" style="display:flex;flex:1;min-width:0;position:relative">${side}<div class="pane">${bar}<div class="r-head" style="color:${head.color}"><b>${esc(head.name)}</b><b>${items.length}</b></div><div class="r-body">${rows || '<div class="r-none">No Reminders</div>'}</div></div>${alertBox(u.alert)}</div>`;
  },
  on: { list(s, id) { s.ui.list = id; }, tog(s, id) { const i = s.items.find(i => i.id === id); i.done = !i.done; }, add(s) { const l = s.lists.find(l => l.id === s.ui.list) || s.lists[0]; s.items.push({id: 'x' + s.items.length, list: l.id, title: 'New Reminder', done: false, flag: false}); }, alert: answer, search(s, _, t) { s.ui.q = t; }, show(s) { s.ui.show = !s.ui.show; } },
  menus(s) { return [{label: 'File', items: [{label: 'New Reminder', shortcut: '⌘N', act: 'add'}, {label: 'New List', shortcut: '⇧⌘N'}, {label: 'New Section', shortcut: '⌥⌘N'}, '-', {label: 'Print…', shortcut: '⌘P'}]}, editMenu, {label: 'View', items: [{label: s.ui.show ? 'Hide Completed' : 'Show Completed', shortcut: '⇧⌘H', act: 'show'}, {label: 'Sort By', items: [{label: 'Manual'}, {label: 'Due Date'}, {label: 'Priority'}, {label: 'Title'}]}, {label: 'as List'}, {label: 'as Columns'}, '-', {label: 'Hide Sidebar', shortcut: '⌥⌘S'}]}]; },
});

// ------------------------------------------------------------------ Safari
TE.register('safari', {
  title: 'Safari', size: [1080, 660],
  render(s) {
    const u = s.ui, t = s.tabs.find(t => t.id === s.active) || s.tabs[0], pg = s.pages[t.page];
    const bar = `<div class="tbar s-bar" data-windrag style="${u.side ? '' : 'padding-left:84px'}">${tb('sidebar.left', 'Sidebar', {act: 'side', fn: 'show or hide the sidebar'})}${tb('chevron.left', 'Back', {act: 'back', dim: !t.back.length, fn: 'go back one page', noun: 'arrow'})}${tb('chevron.right', 'Forward', {act: 'fwd', dim: !t.fwd.length, fn: 'go forward one page', noun: 'arrow'})}<span class="sp"></span>` +
      `<span class="s-addr"${A('address field', 'Address and search field', {fn: 'type a web address|search the web'})}>${sym('lock', 11)}<input type="text" value="${esc(u.addr != null ? u.addr : pg.host)}" data-input="addr" data-enter="goaddr" data-focus="addr">${tb('arrow.clockwise', 'Reload', {fn: 'reload this page', size: 13})}</span><span class="sp"></span>` +
      tb('square.and.arrow.up', 'Share', {fn: 'share this page'}) + tb('plus', 'New Tab', {act: 'newtab', fn: 'open a new tab'}) + tb('rectangle.on.rectangle', 'Tab Overview', {fn: 'show all tabs'}) + `</div>`;
    const tabs = `<div class="s-tabs">${s.tabs.map(x => `<span class="s-tab${x.id === t.id ? ' on' : ''}"${A('tab', s.pages[x.page].title, {act: 'tab', arg: x.id, state: x.id === t.id ? 'selected' : '', fn: `switch to the ${s.pages[x.page].title} tab`})}><i class="s-x"${A('button', 'Close Tab', {act: 'closetab', arg: x.id, fn: `close the ${s.pages[x.page].title} tab`, icon: 1})}>${sym('xmark', 8)}</i><span>${esc(s.pages[x.page].title)}</span></span>`).join('')}</div>`;
    const favs = `<div class="s-favs">${s.favs.map(f => `<span${A('link', f.title, {act: 'nav', arg: f.page, fn: `open the ${f.title} favourite`})}>${esc(f.title)}</span>`).join('')}</div>`;
    const link = (l, cls = '') => `<a class="${cls}"${A('link', l.text, {act: l.page ? 'nav' : '', arg: l.page})}>${esc(l.text)}</a>`;
    let page = `<div class="s-top" style="background:${pg.color}"><b>${esc(pg.site)}</b><span>${pg.nav.map(l => link(l)).join('')}</span><span class="pbtn big${pg.cta_def ? ' def' : ''}"${A('button', pg.cta)}>${esc(pg.cta)}</span></div>`;
    if (pg.kind === 'article') page += `<div class="s-art"><em>${esc(pg.section)}</em><h1>${esc(pg.h1)}</h1><small>${esc(pg.by)}</small>${pg.paras.map(p => `<p>${esc(p)}</p>`).join('')}<div class="s-rel"><b>Related</b>${pg.links.map(l => link(l)).join('')}</div></div>`;
    else if (pg.kind === 'shop') page += `<div class="s-shop">${pg.items.map(i => `<div class="s-card"><div style="background:${hueBg(i.hue)}"></div><b>${esc(i.name)}</b><span>${esc(i.price)}</span><span class="pbtn"${A('button', 'Add to Bag', {fn: `add ${i.name} to the bag`})}>Add to Bag</span></div>`).join('')}</div>`;
    else if (pg.kind === 'results') page += `<div class="s-res"><span class="s-q"${A('search field', 'Search ' + pg.site, {fn: 'search this site'})}>${sym('magnifyingglass', 14)}<span>${esc(pg.query)}</span></span>${pg.results.map(r => `<div>${link(r, 'big')}<small>${esc(r.url)}</small><p>${esc(r.desc)}</p></div>`).join('')}</div>`;
    else page += `<div class="s-form"><h1>${esc(pg.h1)}</h1>${pg.fields.map(f => `<label><span>${esc(f)}</span><input type="text" class="fld"${A('text field', f)} data-input="form" data-arg="${esc(f)}" data-focus="f-${esc(f)}"></label>`).join('')}<label class="chk"><span class="cb${pg.keep ? ' on' : ''}"${A('checkbox', pg.check, {state: pg.keep ? 'checked' : 'unchecked'})}>${pg.keep ? sym('checkmark', 9) : ''}</span>${esc(pg.check)}</label><div><span class="pbtn big def"${A('button', pg.submit, {act: 'submit'})}>${esc(pg.submit)}</span><span class="pbtn big"${A('button', pg.alt)}>${esc(pg.alt)}</span></div></div>`;
    const side = !u.side ? '' : `<div class="side s-side"><div class="sh">Bookmarks</div>${s.favs.map(f => `<div class="si"${A('bookmark', f.title, {act: 'nav', arg: f.page})}>${sym('book', 15)}<span>${esc(f.title)}</span></div>`).join('')}<div class="sh">Reading List</div>${s.reading.map(r => `<div class="si"${A('bookmark', r)}>${sym('doc.text', 15)}<span>${esc(r)}</span></div>`).join('')}</div>`;
    return `<div class="saf" style="display:flex;flex:1;min-width:0;position:relative">${side}<div class="pane">${bar}${tabs}${s.showFavs ? favs : ''}<div class="s-page">${page}</div></div>${alertBox(u.alert)}</div>`;
  },
  on: { side(s) { s.ui.side = !s.ui.side; }, tab(s, id) { s.active = id; s.ui.addr = null; }, newtab(s) { const id = 't' + (s.tabs.length + 1) + 'n'; s.tabs.push({id, page: s.home, back: [], fwd: []}); s.active = id; TE.focus('addr', true); },
    closetab(s, id) { if (s.tabs.length > 1) { s.tabs = s.tabs.filter(t => t.id !== id); if (s.active === id) s.active = s.tabs[0].id; } }, nav(s, page) { const t = s.tabs.find(t => t.id === s.active); if (page && s.pages[page]) { t.back.push(t.page); t.fwd = []; t.page = page; s.ui.addr = null; } },
    back(s) { const t = s.tabs.find(t => t.id === s.active); if (t.back.length) { t.fwd.push(t.page); t.page = t.back.pop(); } }, fwd(s) { const t = s.tabs.find(t => t.id === s.active); if (t.fwd.length) { t.back.push(t.page); t.page = t.fwd.pop(); } },
    addr(s, _, v) { s.ui.addr = v; }, goaddr(s, _, v) { const q = v.trim().toLowerCase(), k = Object.keys(s.pages).find(k => s.pages[k].host === q || s.pages[k].host === 'www.' + q); this.on.nav(s, k || s.searchPage); if (!k) s.pages[s.searchPage].query = v.trim(); }, form(s, f, v) { s.form[f] = v; }, submit(s) { s.submitted = {...s.form}; }, alert: answer },
  menus(s) { return [{label: 'File', items: [{label: 'New Window', shortcut: '⌘N'}, {label: 'New Private Window', shortcut: '⇧⌘N'}, {label: 'New Tab', shortcut: '⌘T', act: 'newtab'}, '-', {label: 'Open Location…', shortcut: '⌘L'}, {label: 'Close Tab', shortcut: '⌘W'}, '-', {label: 'Save As…', shortcut: '⌘S'}, {label: 'Print…', shortcut: '⌘P'}]}, editMenu,
    {label: 'View', items: [{label: s.showFavs ? 'Hide Favourites Bar' : 'Show Favourites Bar', shortcut: '⇧⌘B', act: 'favbar'}, {label: 'Show Tab Bar'}, {label: s.ui.side ? 'Hide Sidebar' : 'Show Sidebar', shortcut: '⇧⌘L', act: 'side'}, '-', {label: 'Reload Page', shortcut: '⌘R'}, {label: 'Zoom In', shortcut: '⌘+'}, {label: 'Zoom Out', shortcut: '⌘-'}, {label: 'Enter Full Screen', shortcut: '⌃⌘F'}]},
    {label: 'History', items: [{label: 'Show All History', shortcut: '⌘Y'}, {label: 'Back', shortcut: '⌘[', act: 'back'}, {label: 'Forward', shortcut: '⌘]', act: 'fwd'}, '-', {label: 'Reopen Last Closed Tab', shortcut: '⇧⌘T'}, {label: 'Clear History…'}]}, {label: 'Bookmarks', items: [{label: 'Show Bookmarks', shortcut: '⌃⌘1'}, {label: 'Add Bookmark…', shortcut: '⌘D'}, {label: 'Add to Reading List', shortcut: '⇧⌘D'}, '-', ...s.favs.map(f => ({label: f.title, act: 'nav', arg: f.page}))]}]; },
});
TE.apps.safari.on.favbar = s => { s.showFavs = !s.showFavs; };

// ------------------------------------------------------------------ System Settings
TE.register('settings', {
  title: 'System Settings', size: [820, 600],
  render(s) {
    const u = s.ui, cur = s.panes.find(p => p.id === u.pane), badge = (p, z) => `<span class="st-b" style="background:${p.color};width:${z}px;height:${z}px">${sym(p.sym, z * .64)}</span>`;
    const ctl = r => r.t === 'switch' ? `<span class="sw${r.v ? ' on' : ''}"${A('switch', r.label, {act: 'sw', arg: r.k, state: r.v ? 'on' : 'off', fn: `turn ${r.v ? 'off' : 'on'} ${r.label}`})}><i></i></span>`
      : r.t === 'popup' ? `<span class="popup"${A('pop-up button', r.label, {act: 'pop', arg: r.k, fn: `change ${r.label}`})}>${esc(r.v)}<em>${sym('chevron.down', 9)}</em></span>`
      : r.t === 'stepper' ? `<span class="st-val">${esc(r.v)}${r.unit || ''}</span><span class="stp"><span${A('button', 'Increase ' + r.label, {act: 'step', arg: r.k + '+', icon: 1, noun: 'arrow', fn: `raise ${r.label}`})}>${sym('chevron.up', 7)}</span><span${A('button', 'Decrease ' + r.label, {act: 'step', arg: r.k + '-', icon: 1, noun: 'arrow', fn: `lower ${r.label}`})}>${sym('chevron.down', 7)}</span></span>`
      : r.t === 'slider' ? `${sym(r.lo || 'minus', 12)}<span class="sld" style="--v:${r.v}"${A('slider', r.label, {fn: `adjust ${r.label}`})}><b></b><i></i></span>${sym(r.hi || 'plus', 12)}`
      : r.t === 'check' ? `<span class="cb${r.v ? ' on' : ''}"${A('checkbox', r.label, {act: 'sw', arg: r.k, state: r.v ? 'checked' : 'unchecked'})}>${r.v ? sym('checkmark', 9) : ''}</span>`
      : r.t === 'button' ? `<span class="pbtn"${A('button', r.v, {fn: r.fn || ''})}>${esc(r.v)}</span>` : `<span class="sub" style="font-size:13px">${esc(r.v)}</span>`;
    const side = `<div class="side st-side"><div style="padding:0 10px 8px">${srch('Search', 'width:100%')}</div><div class="st-acc"${A('sidebar item', s.user, {fn: 'open the Apple Account settings'})}>${avatar(s.user, s.hue, 36)}<span><b>${esc(s.user)}</b><small>Apple Account</small></span></div>` +
      s.panes.map(p => `${p.gap ? '<i class="st-gap"></i>' : ''}` + si('blue', u.pane === p.id, 'sidebar item', p.name, {act: 'pane', arg: p.id, fn: `open ${p.name} settings`}, `${badge(p, 20)}<span>${esc(p.name)}</span>`)).join('') + `</div>`;
    const groups = (s.rows[u.pane] || []).map(g => `${g.title ? `<div class="st-gt">${esc(g.title)}</div>` : ''}<div class="st-card">${g.rows.map(r => `<div class="st-row"><span>${esc(r.label)}${r.sub ? `<small>${esc(r.sub)}</small>` : ''}</span><span class="st-c">${ctl(r)}</span></div>`).join('')}</div>`).join('');
    return `<div class="sett" style="display:flex;flex:1;min-width:0;position:relative">${side}<div class="pane st-main"><div class="tbar clear" data-windrag>${tb('chevron.left', 'Back', {dim: 1, noun: 'arrow'})}${tb('chevron.right', 'Forward', {dim: 1, noun: 'arrow'})}<span class="ttl">${esc(cur.name)}</span></div><div class="st-body"><div class="st-card st-hd">${badge(cur, 32)}<span><b>${esc(cur.name)}</b><small>${esc(cur.blurb)}</small></span></div>${groups}</div></div>${alertBox(u.alert)}</div>`;
  },
  on: { pane(s, id) { s.ui.pane = id; }, sw(s, k) { const r = this.row(s, k); r.v = !r.v; }, step(s, a) { const r = this.row(s, a.slice(0, -1)); r.v = +r.v + (a.endsWith('+') ? 1 : -1) * (r.by || 1); },
    pop(s, k, e, el) { const r = this.row(s, k), b = el.getBoundingClientRect(); TE.menu(r.opts.map(o => ({label: o, checked: o === r.v})), b.left - 12, b.bottom + 3, it => { r.v = it.label; TE.refresh('settings'); }); return false; }, alert: answer, search(s, _, t) { s.ui.q = t; } },
  row(s, k) { for (const p in s.rows) for (const g of s.rows[p]) for (const r of g.rows) if (r.k === k) return r; },
  menus(s) { return [{label: 'File', items: [{label: 'Close', shortcut: '⌘W', sys: 'close'}]}, editMenu, {label: 'View', items: s.panes.map(p => ({label: p.name, act: 'pane', arg: p.id, checked: p.id === s.ui.pane}))}]; },
});

// ------------------------------------------------------------------ Messages
TE.register('messages', {
  title: 'Messages', size: [900, 600],
  render(s) {
    const u = s.ui, c = s.chats.find(c => c.id === u.chat);
    const side = `<div class="side msg-side" data-windrag><div class="mg-top"><span class="sp" style="flex:1"></span>${tb('square.and.pencil', 'Compose', {fn: 'start a new conversation|write a new message'})}</div><div style="padding:0 10px 8px">${srch('Search', 'width:100%')}</div>` +
      s.chats.map(x => `<div class="mg-row${x.id === u.chat ? ' on' : ''}"${A('conversation', x.name, {act: 'chat', arg: x.id, state: x.unread ? 'unread' : '', fn: `open the conversation with ${x.name}`})}><i class="dot${x.unread ? ' on' : ''}"></i>${avatar(x.name, x.hue, 40)}<div><div class="r1"><b>${esc(x.name)}</b><span>${esc(x.time)}</span></div><div class="r3">${esc(x.msgs[x.msgs.length - 1].text)}</div></div></div>`).join('') + `</div>`;
    const main = `<div class="pane"><div class="tbar" data-windrag><span class="sub" style="font-size:13px">To:</span><span class="ttl" style="font-weight:500;font-size:13px">${esc(c.name)}</span><span class="sp"></span>${tb('phone', 'Audio Call', {fn: `call ${c.name}`})}${tb('info.circle', 'Details', {fn: 'show details of this conversation'})}</div>` +
      `<div class="mg-body">${c.msgs.map(m => `<div class="bub${m.me ? ' me' : ''}">${esc(m.text)}</div>`).join('')}<div class="mg-del">${c.msgs[c.msgs.length - 1].me ? 'Delivered' : ''}</div></div>` +
      `<div class="mg-in">${tb('plus.circle', 'Apps', {fn: 'add a photo, sticker or more'})}<span class="mg-f"${A('text field', 'iMessage', {fn: 'type a message'})}><input type="text" placeholder="iMessage" value="${esc(u.draft || '')}" data-input="draft" data-enter="send" data-focus="draft"></span>${tb('face.smiling', 'Emoji', {fn: 'pick an emoji'})}${tb('mic', 'Dictate', {fn: 'record an audio message'})}</div></div>`;
    return `<div class="msgs" style="display:flex;flex:1;min-width:0;position:relative">${side}${main}${alertBox(u.alert)}</div>`;
  },
  on: { chat(s, id) { s.ui.chat = id; s.ui.draft = ''; const c = s.chats.find(c => c.id === id); c.unread = false; }, draft(s, _, t) { s.ui.draft = t; }, send(s, _, t) { if (t.trim()) { s.chats.find(c => c.id === s.ui.chat).msgs.push({me: true, text: t.trim()}); s.ui.draft = ''; } }, alert: answer, search(s, _, t) { s.ui.q = t; } },
  menus(s) { return [{label: 'File', items: [{label: 'New Message', shortcut: '⌘N'}, {label: 'Open…', shortcut: '⌘O'}, '-', {label: 'Delete Conversation…', shortcut: '⌘⌫'}, {label: 'Print…', shortcut: '⌘P'}]}, editMenu, {label: 'View', items: [{label: 'All Messages', shortcut: '⌘1'}, {label: 'Known Senders', shortcut: '⌘2'}, {label: 'Unread Messages', shortcut: '⌘4'}, '-', {label: 'Make Text Bigger', shortcut: '⌘+'}, {label: 'Recently Deleted'}]},
    {label: 'Conversation', items: [{label: 'Pin'}, {label: 'Hide Alerts'}, {label: 'Mark as Unread', shortcut: '⇧⌘U'}, '-', {label: 'Send Location'}, {label: 'Share Focus Status'}, {label: 'Block Person…'}]}]; },
});

// ------------------------------------------------------------------ Music
TE.register('music', {
  title: 'Music', size: [1040, 640],
  render(s) {
    const u = s.ui, p = s.player, cur = s.songs.find(x => x.id === p.cur) || s.songs[0], pl = s.playlists.find(x => x.id === u.view);
    const nav = (id, name, sy, fn) => si('', u.view === id, 'sidebar item', name, {act: 'view', arg: id, fn}, `${sym(sy, 16)}<span>${esc(name)}</span>`);
    const side = `<div class="side mu-side"><div style="padding:0 10px 8px">${srch('Search', 'width:100%')}</div>${nav('home', 'Home', 'house', 'go to the Music home page')}${nav('new', 'New', 'square.grid.2x2', 'browse new releases')}${nav('radio', 'Radio', 'music.mic', 'listen to the radio')}<div class="sh">Library</div>${nav('recent', 'Recently Added', 'clock', 'show recently added music')}${nav('artists', 'Artists', 'music.microphone', 'browse by artist')}${nav('albums', 'Albums', 'rectangle.stack', 'show all albums|browse the albums')}${nav('songs', 'Songs', 'music.note', 'show all songs|list every song')}<div class="sh">Playlists</div>` +
      s.playlists.map(x => si('', u.view === x.id, 'playlist', x.name, {act: 'view', arg: x.id, fn: `open the ${x.name} playlist`}, `${sym('music.note.list', 16)}<span>${esc(x.name)}</span>`)).join('') + `</div>`;
    const bar = `<div class="tbar mu-bar" data-windrag>${tb('shuffle', 'Shuffle', {act: 'shuffle', on: p.shuffle, state: p.shuffle ? 'on' : 'off', fn: 'play songs in a random order', size: 15})}${tb('backward', 'Previous', {act: 'prev', fn: 'go to the previous song|skip back', size: 19})}${tb(p.playing ? 'pause' : 'play', p.playing ? 'Pause' : 'Play', {act: 'play', fn: p.playing ? 'pause the music' : 'start playing', size: 21})}${tb('forward', 'Next', {act: 'next', fn: 'skip to the next song', size: 19})}${tb('repeat', 'Repeat', {act: 'repeat', on: p.repeat, state: p.repeat ? 'on' : 'off', fn: 'repeat the current playlist', size: 15})}` +
      `<div class="mu-lcd"><i style="background:${hueBg(cur.hue)}"></i><div><b>${esc(cur.title)}</b><span>${esc(cur.artist)} — ${esc(cur.album)}</span><em><u style="width:${p.pos * 100}%"></u></em></div></div>` +
      `${sym('speaker', 13)}<span class="sld mu-vol" style="--v:${p.vol}"${A('slider', 'Volume', {fn: 'change the volume'})}><b></b><i></i></span>${sym('speaker.wave.2', 15)}<span class="sp"></span>${tb('quote.bubble', 'Lyrics', {fn: 'show the lyrics'})}${tb('list.bullet', 'Playing Next', {fn: 'show what plays next'})}</div>`;
    const body = u.view === 'albums' || u.view === 'home' || u.view === 'recent' ? `<div class="mu-h"><b>${u.view === 'home' ? 'Home' : u.view === 'recent' ? 'Recently Added' : 'Albums'}</b></div><div class="mu-grid">${s.albums.map(a => `<div class="mu-al"${A('album', a.title, {fn: `open the album ${a.title}`})}><i style="background:${hueBg(a.hue)}"></i><b>${esc(a.title)}</b><span>${esc(a.artist)}</span></div>`).join('')}</div>`
      : `<div class="mu-h"><b>${esc(pl ? pl.name : u.view === 'artists' ? 'Artists' : 'Songs')}</b><span class="pbtn big def"${A('button', 'Play', {fn: 'play all of these songs'})}>${sym('play', 11)} Play</span><span class="pbtn big"${A('button', 'Shuffle', {fn: 'shuffle these songs'})}>${sym('shuffle', 11)} Shuffle</span></div>` +
        `<div class="mu-th"><span>Title</span><span>Artist</span><span>Album</span><span>Time</span></div><div class="mu-rows">${s.songs.filter(x => !pl || pl.songs.includes(x.id)).map(x => `<div class="mu-row${x.id === u.sel ? ' on' : ''}"${A('song', x.title, {act: 'sel', arg: x.id, state: x.id === p.cur ? 'playing' : ''})} data-dbl="song"><span class="t"><i style="background:${hueBg(x.hue)}"></i>${esc(x.title)}${x.love ? sym('star', 10) : ''}</span><span>${esc(x.artist)}</span><span>${esc(x.album)}</span><span>${esc(x.time)}</span></div>`).join('')}</div>`;
    return `<div class="mus" style="display:flex;flex:1;min-width:0;position:relative">${side}<div class="pane">${bar}${body}</div>${alertBox(u.alert)}</div>`;
  },
  on: { view(s, v) { s.ui.view = v; }, sel(s, id) { s.ui.sel = id; }, song(s, id) { s.player.cur = id; s.player.playing = true; }, play(s) { s.player.playing = !s.player.playing; }, shuffle(s) { s.player.shuffle = !s.player.shuffle; }, repeat(s) { s.player.repeat = !s.player.repeat; },
    next(s) { const i = s.songs.findIndex(x => x.id === s.player.cur); s.player.cur = s.songs[(i + 1) % s.songs.length].id; }, prev(s) { const i = s.songs.findIndex(x => x.id === s.player.cur); s.player.cur = s.songs[(i - 1 + s.songs.length) % s.songs.length].id; }, alert: answer, search(s, _, t) { s.ui.q = t; } },
  menus(s) { return [{label: 'File', items: [{label: 'New', items: [{label: 'Playlist', shortcut: '⌘N'}, {label: 'Smart Playlist…'}, {label: 'Playlist Folder'}]}, {label: 'Import…', shortcut: '⌘O'}, '-', {label: 'Library', items: [{label: 'Update Cloud Library'}, {label: 'Show Duplicate Items'}]}]}, editMenu, {label: 'Song', items: [{label: 'Get Info', shortcut: '⌘I'}, {label: 'Favourite'}, {label: 'Add to Playlist', items: s.playlists.map(p => ({label: p.name}))}, '-', {label: 'Play Next'}, {label: 'Play Last'}, {label: 'Delete from Library'}]},
    {label: 'View', items: [{label: 'Show Sidebar'}, {label: 'Show Playing Next'}, {label: 'Show Lyrics'}, '-', {label: 'Show MiniPlayer'}, {label: 'Enter Full Screen', shortcut: '⌃⌘F'}]}, {label: 'Controls', items: [{label: s.player.playing ? 'Pause' : 'Play', shortcut: 'Space', act: 'play'}, {label: 'Next', shortcut: '⌘→', act: 'next'}, {label: 'Previous', shortcut: '⌘←', act: 'prev'}, '-', {label: 'Increase Volume', shortcut: '⌘↑'}, {label: 'Decrease Volume', shortcut: '⌘↓'}, '-', {label: 'Shuffle', items: [{label: 'On'}, {label: 'Off'}]}, {label: 'Repeat', items: [{label: 'Off'}, {label: 'All'}, {label: 'One'}]}]}]; },
});
})();
